// Generated from the Erbium showcase catalog and shared Markdown.
import { ShowcaseProviders, ShowcaseSurface } from "../preview";
import { CodeBlock } from "@/registry/erbium/blocks/code-block";
import type { Meta, StoryObj } from "@storybook/react";
import OverviewExample from "./variants/overview";

import CommandsExample from "./variants/commands";

import PromptExample from "./variants/prompt";

import FilesExample from "./variants/files";

import ControlledExample from "./variants/controlled";

import CompositionExample from "./variants/composition";

import OverflowExample from "./variants/overflow";

import LineNumbersExample from "./variants/line-numbers";

import HighlightedLinesExample from "./variants/highlighted-lines";

import StatesExample from "./variants/states";

import ChangingSourceExample from "./variants/changing-source";

import LanguagesExample from "./variants/languages";


const name = "code-block";

const meta = {
  component: CodeBlock,
  parameters: {
    docs: { description: { component: componentDocumentation(name) } },
    layout: "centered",
  },
  tags: ["autodocs"],
} satisfies Meta<typeof CodeBlock>;

export default { ...meta, title: "Blocks/Code Block",  decorators: [(Story, context) => <ShowcaseProviders toast={false && context.viewMode !== "docs"}><ShowcaseSurface><Story /></ShowcaseSurface></ShowcaseProviders>] } satisfies Meta;

type Story = StoryObj;

export const Languages: Story = {
  parameters: {
    docs: {
      description: { story: variantDocumentation(name, "languages") },
      source: { code: "import { CodeBlock } from "@/registry/erbium/blocks/code-block";

export default function CodeBlockLanguagesExample() {
  return (
    <div className="grid w-full max-w-xl gap-group">
      <CodeBlock title="TypeScript" language="typescript" code='const name: string = "Erbium";' />
      <CodeBlock title="Python" language="py" code='print("Hello, Erbium.")' />
      <CodeBlock
        title="Patch"
        language="diff"
        code={'@@ -1,2 +1,2 @@\n const theme = "system";\n-const radius = 4;\n+const radius = 8;'}
      />
      <CodeBlock
        title="Terminal output"
        language="ansi"
        code={"\u001B[32m✓\u001B[0m built in 120ms\n\u001B[33mwarning\u001B[0m: 2 unused exports"}
      />
      <CodeBlock
        title="Plain text"
        language="text"
        code="A readable source without highlighting."
      />
      <CodeBlock
        title="Unknown language"
        language="unknown-language"
        code="Unknown languages use the generic file icon."
      />
    </div>
  );
}
" },
    },
  },
  render: LanguagesExample,
};

